css:
:scope { position: relative; overflow: clip; }
.fh { position: relative; min-height: min(calc(100svh - 72px), 58rem); padding-bottom: 5rem; }
.fh__text { position: relative; z-index: 2; width: min(100% - 168px, 992px); margin-inline: auto; }
.fh__h { font-family: var(--os-font-heading); font-weight: 400; font-size: clamp(3.4rem, 1rem + 5vw, 5.6rem); line-height: 1; letter-spacing: -0.025em; max-width: 15ch; margin: 0 0 .3em; color: var(--os-color-heading); }
.fh__intro { font-size: clamp(1.15rem, 1rem + .5vw, 1.4rem); line-height: 1.5; max-width: 36ch; margin: 0 0 1.6rem; }
.fh__btns { display: flex; flex-wrap: wrap; gap: .75rem; margin-bottom: 1.4rem; }
.fh__btns a { text-decoration: none; }
.fh__btn { display: inline-flex; align-items: center; min-height: 48px; padding: .8rem 1.45rem; border-radius: 999px; font-weight: 700; font-size: 1rem; line-height: 1.1; color: var(--os-color-heading); border: 2px solid transparent; transition: transform .2s ease, filter .2s ease; }
.fh__btn--a { background: linear-gradient(90deg, #a7c25a, #f2cb4a); }
.fh__btn--b { border-color: currentColor; }
.fh__btn:hover { transform: translateY(-1px); filter: saturate(1.15); }
.fh__times { display: flex; flex-wrap: wrap; gap: .3rem 1.5rem; margin: 0 0 .3rem; font-size: 1rem; }
.fh__times span { color: var(--os-color-text-muted); }
.fh__times strong { color: var(--os-color-heading); }
.fh__where { margin: 0; font-size: .95rem; color: var(--os-color-text-muted); }
.fh__scene { position: absolute; inset: auto 0 0 0; height: min(100%, 38rem); z-index: 1; pointer-events: none; }
.fh__scene svg { display: block; width: 100%; height: 100%; overflow: visible; }
.dr { fill: none; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 1; stroke-dashoffset: 1; animation: fh-draw 2.4s cubic-bezier(.5,0,.2,1) forwards; }
.dr--art { stroke: #2d4a33; }
.dr--leaf { stroke: #6b8e36; }
.dr--sun { stroke: #eec02b; stroke-width: 3; }
.dr--faint { opacity: .55; }
.dl1 { animation-delay: .1s; } .dl2 { animation-delay: .2s; } .dl5 { animation-delay: .5s; } .dl16 { animation-delay: 1.6s; } .dl17 { animation-delay: 1.7s; }
.wk { color: #6b8e36; opacity: 0; animation: fh-land .55s ease-out forwards; }
.wk0 { animation-delay: 1.6s; } .wk1 { animation-delay: 1.86s; } .wk2 { animation-delay: 2.12s; } .wk3 { animation-delay: 2.38s; } .wk4 { animation-delay: 2.64s; } .wk5 { animation-delay: 2.9s; } .wk6 { animation-delay: 3.16s; } .wk7 { animation-delay: 3.42s; } .wk8 { animation-delay: 3.68s; }
@keyframes fh-draw { to { stroke-dashoffset: 0; } }
@keyframes fh-land { from { opacity: 0; } to { opacity: .95; } }
@media (prefers-reduced-motion: reduce) { .dr { animation: none; stroke-dashoffset: 0; } .wk { animation: none; opacity: .9; } }
@media (max-width: 1199px) { .fh { min-height: 0; padding-bottom: calc(100% * .52 + 1rem); } .fh__h { font-size: clamp(2.9rem, 1.2rem + 6vw, 5.8rem); max-width: 12ch; } .fh__scene { height: auto; aspect-ratio: 1200 / 640; } }
@media (max-width: 767px) { .fh__text { width: calc(100% - 100px); } .fh__intro { font-size: 1.15rem; } .fh__btns { flex-direction: column; align-items: flex-start; } }
